  ('2026-11-21'::date, 'Synaxis of the Holy Archangel Michael and the Other Bodiless Powers.'),
  ('2026-11-22'::date, 'Twenty-Fifth Sunday after Pentecost. Holy Martyrs Onesiphorus and Porphyrius. And our Venerable Mother Matrona. And Venerable Theoktista of Lesbos — her service is to be chanted at Compline. Our Venerable Father Simeon the Logothete (Metaphrastes). Our Holy Father Nectarios of Aegina, Wonderworker, Bishop of Pentapolis.'),
  ('2026-11-23'::date, 'Holy Apostles Erastus, Olympas, Rodion and those with them.'),
  ('2026-11-24'::date, 'Holy Martyrs Menas, Victor and Vincent. And our Venerable Father and Confessor Theodore the Studite — his service is to be chanted at Compline. Holy Great Martyr Stefan of Dečani, King of Serbia.'),
  ('2026-11-25'::date, 'Our Holy Father John the Merciful, Archbishop of Alexandria. And our Venerable Father Nilus.'),
  ('2026-11-26'::date, 'Our Holy Father John Chrysostom, Archbishop of Constantinople.'),
  ('2026-11-27'::date, 'Holy and All-Praised Apostle Philip. And our Holy Father Gregory Palamas, Archbishop of Thessalonica — his service is to be chanted at Compline.'),
  ('2026-11-28'::date, 'Beginning of the Nativity Fast. Holy Martyrs Gurias, Samonas and Abibus.'),
  ('2026-11-29'::date, 'Twenty-Sixth Sunday after Pentecost. Holy Apostle and Evangelist Matthew.'),
  ('2026-11-30'::date, 'Our Holy Father Gregory, Bishop of Neocaesarea, Wonderworker. Venerable Sebastian of Jackson.'),
  ('2026-12-01'::date, 'Holy Martyr Plato. And Holy Martyr Romanus.'),
  ('2026-12-02'::date, 'Holy Prophet Obadiah. And Holy Martyr Barlaam. Our Venerable and God-bearing Fathers Barlaam and Joasaph, Prince of India. Venerable Porphyrios of Kavsokalyvia.'),
  ('2026-12-03'::date, 'Forefeast of the Entry of the Most Holy Theotokos into the Temple. And Venerable Gregory the Decapolite. And our Holy Father Proclus, Archbishop of Constantinople.'),
  ('2026-12-04'::date, 'The Entry of Our Most Holy Lady Theotokos into the Temple.'),
  ('2026-12-05'::date, 'Afterfeast of the Entry of the Most Holy Theotokos into the Temple. Holy Apostle Philemon and those with him. Our Venerable and God-bearing Fathers Simeon and Sava, founders of the sacred Monastery of Hilandar.'),
  ('2026-12-06'::date, 'Twenty-Seventh Sunday after Pentecost. Afterfeast of the Entry of the Most Holy Theotokos into the Temple. Our Holy Father Amphilochius, Bishop of Iconium. And our Holy Father Gregory, Bishop of Agrigentum — his service is to be chanted at Compline.'),
  ('2026-12-07'::date, 'Afterfeast of the Entry of the Most Holy Theotokos into the Temple. Holy Great Martyr Catherine. And Holy Great Martyr Mercurius.'),
  ('2026-12-08'::date, 'Apodosis of the Feast of the Entry of Our Most Holy Lady Theotokos into the Temple. Our Holy Father, Hieromartyr Clement, Pope of Rome. And our Holy Father, Hieromartyr Peter of Alexandria.'),
  ('2026-12-09'::date, 'Our Venerable Father Alypius the Stylite. Consecration of the Church of the Great Martyr George in Kyiv, before the gates of Hagia Sophia.'),
  ('2026-12-10'::date, 'Holy Martyr James the Persian. And our Venerable Father Palladius — his service is to be chanted at Compline.'),
  ('2026-12-11'::date, 'Holy Venerable Martyr Stephen the New. And Holy Martyr Irenarchus — his service is to be chanted at Compline. And Holy Martyr Christo.'),
  ('2026-12-12'::date, 'Holy Martyr Paramon. And Holy Martyr Philoumenus — although he is mentioned in the Typikon, there is no service for him in the Menaia. And our Venerable Father Acacius of Sinai — his service is to be chanted at Compline. Saint Mardarije, Bishop of America and Canada.'),
  ('2026-12-13'::date, 'Twenty-Eighth Sunday after Pentecost. Holy and All-Praised Apostle Andrew the First-Called.'),
  ('2026-12-14'::date, 'Holy Prophet Nahum.'),
  ('2026-12-15'::date, 'Holy Prophet Habakkuk. And Holy and Blessed Uroš V, Emperor of Serbia. And our Venerable Father Joanikije of Devič, Wonderworker.'),
  ('2026-12-16'::date, 'Holy Prophet Zephaniah.'),
  ('2026-12-17'::date, 'Holy Great Martyr Barbara. And our Venerable Father John of Damascus.'),
  ('2026-12-18'::date, 'Our Venerable Father Sabbas the Sanctified.'),
  ('2026-12-19'::date, 'Our Holy Father Nicholas, Archbishop of Myra in Lycia.'),
  ('2026-12-20'::date, 'Twenty-Ninth Sunday after Pentecost. Our Holy Father Ambrose, Bishop of Mediolanum (Milan). And our Venerable and God-bearing Father Gregory the Silent of Gornjak, the Sinaite.'),
  ('2026-12-21'::date, 'Our Venerable Father Patapius.'),
  ('2026-12-22'::date, 'Conception of Saint Anna, when she conceived the Most Holy Theotokos.'),
  ('2026-12-23'::date, 'Holy Martyrs Menas, Hermogenes and Eugraphus. And Saint Jovan, Serbian Despot.'),
  ('2026-12-24'::date, 'Our Venerable Father Daniel the Stylite.'),
  ('2026-12-25'::date, 'Our Holy Father Spyridon, Bishop of Trimythous, Wonderworker.'),
  ('2026-12-26'::date, 'Holy Martyrs Eustratius, Auxentius, Eugene, Mardarius and Orestes. Holy Hieromartyr Gavrilo, Patriarch of Serbia.'),
  ('2026-12-27'::date, 'Sunday of the Holy Forefathers. Holy Martyrs Thyrsus, Leucius, Philemon, Apollonius and Arianus — their service is to be chanted at Compline.'),
  ('2026-12-28'::date, 'Holy Hieromartyr Eleutherius. And our Venerable Father Paul of Mount Latros, Wonderworker.'),
  ('2026-12-29'::date, 'Holy Prophet Haggai.'),
  ('2026-12-30'::date, 'Holy Prophet Daniel. And the Three Holy Youths: Ananias, Azarias and Misael. And Venerable New Martyrs Paisije and Avakum, and those who suffered with them in Belgrade.'),
  ('2026-12-31'::date, 'Holy Martyr Sebastian and his companions. And the Hierarch of Christ Modestus, Patriarch of Jerusalem — his service is to be chanted at Compline.')
)
insert into public.calendar_day_translations (
  calendar_day_id,
  language_code,
  title,
  saints,
  details,
  fasting_note
)
select
  d.id,
  'en',
  p.title,
  array[]::text[],
  null,
  null
from payload p
join public.calendar_days d
  on d.country_code = 'RS'
 and d.calendar_code = 'rs-serbian-orthodox-church'
 and d.language_code = 'sr'
 and d.calendar_date = p.calendar_date
on conflict (calendar_day_id, language_code) do update set
  title = excluded.title,
  saints = excluded.saints,
  details = excluded.details,
  fasting_note = excluded.fasting_note;

do $$
declare
  en_count integer;
begin
  select count(*)
    into en_count
  from public.calendar_day_translations t
  join public.calendar_days d on d.id = t.calendar_day_id
  where d.country_code = 'RS'
    and d.calendar_code = 'rs-serbian-orthodox-church'
    and d.calendar_date between date '2026-01-01' and date '2026-12-31'
    and t.language_code = 'en';

  if en_count <> 365 then
    raise exception 'Expected 365 RS English translations; found %', en_count;
  end if;
end
$$;

commit;